class Shape:
    def area(self):
        raise NotImplementedError("Subclasses must implement area()")

class Rectangle(Shape):
    def __init__(self, w, h):
        self.w, self.h = w, h
    def area(self):
        return self.w * self.h

class Circle(Shape):
    def __init__(self, r):
        self.r = r
    def area(self):
        return round(3.14159 * self.r ** 2, 2)

shapes = [Rectangle(3, 4), Circle(2)]
for s in shapes:
    print(type(s).__name__, s.area())
print(isinstance(shapes[0], Shape), isinstance(shapes[0], Circle), issubclass(Circle, Shape))

